SELECT f.feature_id || ' → ' || n.entity_name || ': документ истории называет ' || n.said_id || ', а фича его не называет' AS detail FROM project_named_id n JOIN project_feature_stories f ON f.project_id = n.project_id AND f.story_id = n.entity_name WHERE n.project_id = $1 AND n.entity_kind = 'story' AND n.said_id LIKE 'FR-%' AND n.heads_row AND NOT n.caveated AND EXISTS (SELECT 1 FROM project_requirements r WHERE r.project_id = n.project_id AND r.id = n.said_id) AND NOT EXISTS (SELECT 1 FROM project_named_id m WHERE m.project_id = n.project_id AND m.entity_kind = 'feature' AND m.entity_name = f.feature_id AND m.said_id = n.said_id) AND true ORDER BY 1
